 "territorio.lead": {"it": "Il borgo di San Raffaele Alto e il paesaggio che lo circonda.", "en": "The village of San Raffaele Alto and the landscape around it."},
 "territorio.sm.0": {"it": "Cos’è il Moon Festival", "en": "What Moon Festival is"},
 "territorio.sm.1": {"it": "Note di regia · 2026", "en": "Director’s notes · 2026"},
