 "alt.Ilum-collettivo_MoonFestival_5ed_luce-rossa": {"it": "Un ragazzo in una luce rossa tra le installazioni del festival.", "en": "A young man in red light among the festival installations."},
 "credito.Ilum-collettivo_MoonFestival_5ed_luce-rossa": {"it": "© Ilum collettivo · Moon Festival, 5ª edizione", "en": "© Ilum collettivo · Moon Festival, 5th edition"},
 "partner.s2.o": {"it": "Diventa partner", "en": "Become a partner"},
 "partner.s2.h": {"it": "Non è solo sostegno. È connessione.", "en": "It is not just support. It is connection."},
 "partner.s2.p0": {"it": "Il Moon Festival è una rete di supporto reciproco tra il festival e le realtà economiche del territorio: un modo per valorizzare le attività locali e creare connessioni con artist*, pubblici e altre realtà.", "en": "Moon Festival is a network of mutual support between the festival and local businesses: a way to showcase local activity and build connections with artists, audiences and other organisations."},
